const DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS: u64 = 3_600;

/// Current unix time in whole seconds.
pub fn now_unix() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// High-level facade over the graph store and the ingestion pipeline.
pub struct MindLeak {
    store: GraphStore,
    consolidation_min_interval_secs: u64,
    consolidator: consolidate::Consolidator,
    embedder: Box<dyn embed::TextEmbedder>,
    recall_floor: f64,
    /// The checkout this process serves, used to make incoming absolute paths
    /// repo-relative. Injected rather than reached for: the core has no business
    /// knowing where on disk it is, and tests must be able to set it.
    workspace_root: Option<String>,
    /// The other worktrees of this same repository. All of them share one graph
    /// (ADR-0038), so a file saved in any of them has the one repo-relative id;
    /// without these, a sibling checkout's path cannot be placed and is refused.
    ///
    /// Behind a lock because the set is not fixed for the life of the process:
    /// this fleet creates worktrees hourly, and one resolved at startup goes
    /// stale the moment the next `git worktree add` runs.
    worktree_roots: RwLock<Vec<String>>,
    /// How to re-resolve the roots when a path lands outside all of them.
    ///
    /// Injected for the same reason the roots are: the core has no business
    /// spawning git, and a test must be able to make a new root appear without
    /// one. Absent, the behaviour is exactly what it was before - a miss is a
    /// refusal.
    worktree_refresh: Option<Box<dyn Fn() -> Vec<String> + Send + Sync>>,
    /// How to ask whether a commit id names a real commit in this checkout.
    ///
    /// Injected for the same reason the refresh above is: the core does not
    /// spawn git, and a test must be able to answer for a commit that does not
    /// exist without creating one. Absent - and when a resolver answers `None`
    /// because git could not be reached - the behaviour is exactly what it was
    /// before: the shape check alone decides.
    commit_resolver: Option<Box<CommitResolver<'static>>>,
    /// When the roots were last re-resolved, so a genuinely foreign path cannot
    /// make every refusal pay for a git subprocess.
    last_refresh: Mutex<Option<Instant>>,
}

/// The shortest gap between two root re-resolutions.
///
/// A path outside the repository is refused on every ingest a badly-configured
/// sensor makes, and each refusal would otherwise spawn git. Long enough that a
/// storm costs one subprocess, short enough that a worktree created mid-session
/// is picked up while the agent is still working in it.
const WORKTREE_REFRESH_INTERVAL: Duration = Duration::from_secs(5);

/// Borrow a resolved root list for the placing helpers, which take `&[&str]`.
fn borrowed(roots: &[String]) -> Vec<&str> {
    roots.iter().map(String::as_str).collect()
}

/// How the engine asks whether a commit id names a real commit in this checkout.
///
/// `Some(false)` is git answering "no". `None` is git failing to answer at all,
/// which must never be read as "no" - see `MindLeak::with_commit_resolver`.
///
/// Lifetime-generic so a caller can pass a resolver that borrows: the engine
/// stores a `'static` one, but a test asserting what the resolver was asked
/// needs to capture a local.
pub type CommitResolver<'a> = dyn Fn(&str) -> Option<bool> + Send + Sync + 'a;

// The async maintenance worker (`mindleak-mcp`) moves a `MindLeak` into
// `std::thread::spawn`, so `MindLeak` must stay `Send`. This fails to compile if
// a field regresses that (e.g. a non-thread-safe embedder) — the `Send + Sync`
// bound on `embed::TextEmbedder` is what keeps the boxed embedder `Send`.
const _: fn() = || {
    fn assert_send<T: Send>() {}
    assert_send::<MindLeak>();
};

impl MindLeak {
    /// Open (or create) a MindLeak database at `path`.
    pub fn open(path: &str) -> Result<Self> {
        Ok(MindLeak {
            store: GraphStore::new(db::open(path)?),
            consolidation_min_interval_secs: DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS,
            consolidator: consolidate::Consolidator::default(),
            embedder: Box::new(embed::Embedder::default()),
            recall_floor: config::DEFAULT_RECALL_FLOOR,
            workspace_root: None,
            worktree_roots: RwLock::new(Vec::new()),
            worktree_refresh: None,
            commit_resolver: None,
            last_refresh: Mutex::new(None),
        })
    }

    /// Open an ephemeral in-memory graph (tests / tooling).
    pub fn open_in_memory() -> Result<Self> {
        Ok(MindLeak {
            store: GraphStore::new(db::open_in_memory()?),
            consolidation_min_interval_secs: DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS,
            consolidator: consolidate::Consolidator::default(),
            embedder: Box::new(embed::Embedder::default()),
            recall_floor: config::DEFAULT_RECALL_FLOOR,
            workspace_root: None,
            worktree_roots: RwLock::new(Vec::new()),
            worktree_refresh: None,
            commit_resolver: None,
            last_refresh: Mutex::new(None),
        })
    }

    /// Override the optional consolidation model client.
    pub fn with_consolidator(mut self, consolidator: consolidate::Consolidator) -> Self {
        self.consolidator = consolidator;
        self
    }

    /// Declare the checkout this process serves, so absolute paths from editor
    /// sensors collapse onto the same repo-relative node ids the rest of the
    /// fleet writes.
    ///
    /// Every worktree of one repository shares a single graph (ADR-0038), so a
    /// path left absolute splits one file across as many identities as there are
    /// checkouts. Measured before this existed: **871 of 6,144 nodes carried
    /// absolute ids across 7 worktrees, and 590 files existed under two
    /// identities at once** -- including `AGENTS.md`. That splits reinforcement
    /// (so real signal decays like a one-off), hides collisions from
    /// `check_overlap`, and leaves governed bindings covering only one spelling.
    pub fn with_workspace_root(mut self, root: impl Into<String>) -> Self {
        let root = root.into();
        self.workspace_root = (!root.trim().is_empty()).then_some(root);
        self
    }

    /// Declare the other worktree roots of this same repository.
    ///
    /// Passed in rather than discovered here so the placing decision stays pure
    /// and testable, and so an unavailable git degrades to the single-root
    /// behaviour instead of to a wrong answer.
    pub fn with_worktree_roots(mut self, roots: impl IntoIterator<Item = String>) -> Self {
        self.worktree_roots = RwLock::new(
            roots
                .into_iter()
                .filter(|root| !root.trim().is_empty())
                .collect(),
        );
        self
    }

    /// How to re-resolve the worktree roots when a path lands outside them all.
    ///
    /// Without this a root set is frozen at construction, so a worktree created
    /// after the server started is invisible to it forever. This fleet creates
    /// worktrees hourly, which means the frozen set decays from the moment it is
    /// resolved, and fastest exactly when the fleet is busiest.
    ///
    /// Injected for the same reason the roots are: the core does not spawn git,
    /// and a test must be able to make a new root appear without one.
    pub fn with_worktree_refresh(
        mut self,
        refresh: impl Fn() -> Vec<String> + Send + Sync + 'static,
    ) -> Self {
        self.worktree_refresh = Some(Box::new(refresh));
        self
    }

    /// How to ask whether a commit id names a real commit in this checkout.
    ///
    /// A fabricated sha is the worst thing that can enter this graph: afterwards
    /// it is indistinguishable from a real one, and no verb removes a node. It
    /// has already happened here - an agent holding an abbreviation composed the
    /// remaining characters, and the phantom intent node it created carries real
    /// edges to real files until it decays.
    ///
    /// Checking the shape cannot catch that, because the invention was a
    /// perfectly well-formed forty-character hex string. Only git can tell a
    /// plausible object name from a real one - and the core does not spawn git,
    /// so the capability is injected exactly as the worktree refresh is.
    ///
    /// The resolver answers `None` when git could not be reached. That is
    /// "unknown", never "no": an unreachable git must not be able to refuse a
    /// commit that is perfectly real.
    pub fn with_commit_resolver(
        mut self,
        resolver: impl Fn(&str) -> Option<bool> + Send + Sync + 'static,
    ) -> Self {
        self.commit_resolver = Some(Box::new(resolver));
        self
    }

    /// Borrow the injected commit resolver for the ingest path.
    pub(crate) fn commit_resolver(&self) -> Option<&CommitResolver<'static>> {
        self.commit_resolver.as_deref()
    }

    /// Every root a caller-supplied path may be made relative against: this
    /// checkout first, then the repository's other worktrees. One list, so the
    /// save path, the commit sensor and the execution sensor cannot disagree
    /// about which files belong to this repository.
    pub(crate) fn roots(&self) -> Vec<String> {
        let mut roots: Vec<String> = Vec::new();
        roots.extend(self.workspace_root.clone());
        if let Ok(known) = self.worktree_roots.read() {
            roots.extend(known.iter().cloned());
        }
        roots
    }

    /// Re-resolve the roots, at most once per interval and never concurrently.
    ///
    /// Returns whether the set changed, so the caller only retries a placement
    /// that now has something new to succeed against. The interval is what stops
    /// a genuinely foreign path - a misconfigured sensor sending the same path
    /// repeatedly - from paying for a git subprocess on every refusal.
    fn refresh_worktree_roots(&self) -> bool {
        let Some(refresh) = self.worktree_refresh.as_ref() else {
            return false;
        };
        // `try_lock` rather than `lock`: if another thread is already refreshing,
        // this one should refuse now rather than queue behind a subprocess to
        // discover the same answer.
        let Ok(mut last) = self.last_refresh.try_lock() else {
            return false;
        };
        if let Some(at) = *last {
            if at.elapsed() < WORKTREE_REFRESH_INTERVAL {
                return false;
            }
        }
        *last = Some(Instant::now());

        let resolved: Vec<String> = refresh()
            .into_iter()
            .filter(|root| !root.trim().is_empty())
            .collect();
        let Ok(mut known) = self.worktree_roots.write() else {
            return false;
        };
        if *known == resolved {
            return false;
        }
        *known = resolved;
        true
    }

    /// Make a caller-supplied path repo-relative for stable node ids.
    ///
    /// Every known worktree root of this repository is a candidate, so a file
    /// saved in a sibling checkout resolves to the same id as one saved here.
    ///
    /// A path that matches no root re-resolves the set once and tries again: the
    /// likeliest reason for a miss is a worktree created after this server
    /// started, and refusing it would make the fix decay the moment it deployed.
    /// A path under no worktree of this repository is still refused - the retry
    /// changes when the answer is computed, never what counts as belonging.
    pub(crate) fn repo_relative(&self, path: &str) -> String {
        let roots = self.roots();
        let placed = ingest::repo_relative(path, &borrowed(&roots));
        if !ingest::is_absolute_path(&placed) {
            return placed;
        }
        if !self.refresh_worktree_roots() {
            return placed;
        }
        let roots = self.roots();
        ingest::repo_relative(path, &borrowed(&roots))
    }

    /// Collapse node ids that spell their path absolutely onto the repo-relative
    /// id the rest of the fleet writes, merging the two halves' history rather
    /// than choosing between them.
    ///
    /// Idempotent, and cheap enough to run at startup, which is what keeps the
    /// graph healing itself if any producer ever writes an absolute id again.
    ///
    /// The prefix pass needs a declared workspace root and is skipped without
    /// one. Collapsing ids whose repo-relative twin the graph already holds does
    /// not, and runs either way: a server that never declares a workspace is
    /// precisely the case that used to leave a sibling checkout's ids orphaned
    /// forever, because no root ever matched them.
    pub fn repair_workspace_paths(&self) -> Result<graph::RepairOutcome> {
        match self.workspace_root.as_deref() {
            Some(root) => self.store.repair_workspace_paths(root),
            None => {
                let mut outcome = graph::RepairOutcome::default();
                self.store.collapse_known_duplicates(&mut outcome)?;
                Ok(outcome)
            }
        }
    }

    /// Override the immutable decay policy resolved by the hosting process.
    pub fn with_decay_policy(mut self, decay_policy: config::DecayPolicy) -> Self {
        self.store = self.store.with_decay_policy(decay_policy);
        self
    }

    pub fn with_working_set_size(mut self, size: usize) -> Self {
        self.store = self.store.with_working_set_size(size);
        self
    }

    /// Override the cosine floor below which `recall` returns nothing (ADR-0053).
    pub fn with_recall_floor(mut self, floor: f64) -> Self {
        self.recall_floor = floor.clamp(config::MIN_RECALL_FLOOR, config::MAX_RECALL_FLOOR);
        self
    }

    pub fn with_consolidation_min_interval(mut self, seconds: u64) -> Self {
        self.consolidation_min_interval_secs = seconds.clamp(60, 86_400);
        self
    }

    /// Override the semantic-recall embedding backend (ADR-0008). Defaults to a
    /// local `/v1/embeddings` client; tests inject a deterministic or unreachable
    /// embedder so the index→recall→seed path is exercised without a live model.
    pub fn with_embedder(mut self, embedder: Box<dyn embed::TextEmbedder>) -> Self {
        self.embedder = embedder;
        self
    }

    pub fn store(&self) -> &GraphStore {
        &self.store
    }
}

#[cfg(test)]
mod tests {
    use super::MindLeak;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    fn assert_send<T: Send>() {}

    /// The regression: `worktree_roots` was resolved once, at engine
    /// construction, so a worktree created afterwards was invisible to that
    /// server for the rest of its life. Observed 2026-07-30 on servers started
    /// hours earlier, refusing paths from four worktrees that appeared during
    /// the session. A fleet that creates worktrees hourly makes a frozen root
    /// set decay from the moment it is resolved.
    #[test]
    fn a_worktree_that_appears_after_startup_is_picked_up() {
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_workspace_root("C:/repo/main")
            .with_worktree_refresh(|| vec!["C:/repo/sibling".to_string()]);

        // Before the refresh the sibling is unknown, and the path is refused by
        // coming back still absolute.
        let placed = engine.repo_relative("C:/repo/sibling/crates/core/src/lib.rs");

        assert_eq!(
            placed, "crates/core/src/lib.rs",
            "the miss re-resolved the roots and placed it on the retry"
        );
    }

    /// The bound. A misconfigured sensor sends the same foreign path on every
    /// call, and each refusal would otherwise pay for a git subprocess. The
    /// refresh rides on the failure that needs it, and only the first one.
    #[test]
    fn a_foreign_path_refreshes_once_not_on_every_refusal() {
        let calls = Arc::new(AtomicUsize::new(0));
        let counter = Arc::clone(&calls);
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_workspace_root("C:/repo/main")
            .with_worktree_refresh(move || {
                counter.fetch_add(1, Ordering::SeqCst);
                Vec::new()
            });

        for _ in 0..5 {
            let placed = engine.repo_relative("D:/somewhere/else/file.rs");
            assert!(
                crate::ingest::is_absolute_path(&placed),
                "a path under no worktree of this repository is still refused"
            );
        }

        assert_eq!(
            calls.load(Ordering::SeqCst),
            1,
            "five refusals cost one refresh, not five"
        );
    }

    /// Without a refresher the behaviour is exactly what it was: a miss is a
    /// refusal, and nothing reaches for git. This is what keeps every existing
    /// caller and test unaffected.
    #[test]
    fn without_a_refresher_a_miss_is_still_simply_refused() {
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_workspace_root("C:/repo/main");

        let placed = engine.repo_relative("C:/repo/sibling/src/lib.rs");

        assert!(crate::ingest::is_absolute_path(&placed));
    }

    // Regression: an injected trait object without Send made MindLeak unusable
    // by the maintenance worker's std::thread::spawn boundary.
    #[test]
    fn mindleak_remains_send_for_maintenance_workers() {
        assert_send::<MindLeak>();
    }
}
